/* 헤더의 선언 예: 저장 공간을 여기서 만들지 않는다. */
extern unsigned int inventory_revision;
/* 구현 .c 한 곳의 정의 예 */
unsigned int inventory_revision = 1u;

#define TWICE(x) ((x) + (x))
/* TWICE(i++)를 쓰지 않는다: 같은 객체를 순서 없이 수정할 수 있다. */
static int twice_small(int value) { return value + value; }

#include "inventory.h"
#include "inventory.h" /* 가드 덕분에 같은 번역 단위의 중복 포함은 안전하다. */
#include <stdlib.h>
#include <limits.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* NDEBUG 설정과 무관하게 식을 한 번 평가하는 학습용 검사다. */
static void check(int passed, int line)
{
    if (!passed) { fprintf(stderr, "check failed at line %d\n", line); abort(); }
}
#define CHECK(expression) check((expression), __LINE__)

int main(void)
{
    Inventory bag = {0u};
    CHECK(inventory_add(&bag, 0u) == INV_OK);
    CHECK(inventory_add(&bag, 40u) == INV_OK);
    CHECK(inventory_add(&bag, 59u) == INV_OK);
    CHECK(bag.quantity == INVENTORY_LIMIT);
    CHECK(inventory_add(&bag, 1u) == INV_RANGE && bag.quantity == 99u);
    CHECK(inventory_add(&bag, UINT_MAX) == INV_RANGE && bag.quantity == 99u);
    CHECK(inventory_add(NULL, 1u) == INV_ARGUMENT);
    bag.quantity = 100u; /* 깨진 외부 상태도 거부한다. */
    CHECK(inventory_add(&bag, 0u) == INV_RANGE && bag.quantity == 100u);
    CHECK(strcmp(inventory_result_name(INV_OK), "ok") == 0);
    CHECK(strcmp(inventory_result_name(INV_RANGE), "range") == 0);
    CHECK(strcmp(inventory_result_name(INV_ARGUMENT), "argument") == 0);
    CHECK(strcmp(inventory_result_name((InventoryResult)99), "unknown") == 0);
    puts("build: declarations, linkage, inventory contracts OK");
    return 0;
}

#ifndef ATLAS_C13_INVENTORY_H
#define ATLAS_C13_INVENTORY_H

/* enum 상수는 저장 공간을 만들지 않는다. 헤더는 계약을 공개한다. */
enum { INVENTORY_LIMIT = 99 };
typedef struct { unsigned int quantity; } Inventory;
typedef enum { INV_OK, INV_RANGE, INV_ARGUMENT } InventoryResult;

/* 유효한 객체의 수량은 0..INVENTORY_LIMIT. 실패 시 변경하지 않는다. */
InventoryResult inventory_add(Inventory *inventory, unsigned int amount);
const char *inventory_result_name(InventoryResult result);

#endif

#include "inventory.h"
#include <stddef.h>

/* 내부 연결: 다른 번역 단위에서 직접 호출하지 못한다. */
static int fits(unsigned int current, unsigned int amount)
{
    return current <= INVENTORY_LIMIT && amount <= INVENTORY_LIMIT - current;
}

InventoryResult inventory_add(Inventory *inventory, unsigned int amount)
{
    if (inventory == NULL) return INV_ARGUMENT;
    if (!fits(inventory->quantity, amount)) return INV_RANGE;
    inventory->quantity += amount;
    return INV_OK;
}

const char *inventory_result_name(InventoryResult result)
{
    switch (result) {
    case INV_OK: return "ok";
    case INV_RANGE: return "range";
    case INV_ARGUMENT: return "argument";
    default: return "unknown";
    }
}
